#!/bin/bash
set -e
D="$(cd "$(dirname "$0")" && pwd)"
APP="$D/NOVA Shell.app"
echo "Installing NOVA Shell..."
B64=''
if echo "$B64" | base64 -D >/dev/null 2>&1; then D=-D; else D=-d; fi
echo "$B64" | base64 $D > "$APP/Contents/MacOS/novashell.py"
printf '#!/bin/bash
cd "$(dirname "$0)"
python3 novashell.py
' > "$APP/Contents/MacOS/novashell"
chmod +x "$APP/Contents/MacOS/novashell"
command -v python3 >/dev/null && echo Ready || echo 'Python 3 required: brew install python3'
